mapper.update:
UPDATE iam_recovery_code_set
SET replaced_at = #{replacedAt}, version = version + 1
WHERE id = #{setId}
  AND version = #{version}
  AND replaced_at IS NULL

mapper.select:
SELECT code_set.id AS set_id, code_set.account_id, code_set.issued_at, code_set.version, COUNT(code.id) FILTER (WHERE code.used_at IS NULL) AS remaining_count FROM iam_recovery_code_set code_set LEFT JOIN iam_recovery_code code ON code.set_id = code_set.id WHERE code_set.account_id IN
#{accountId}
AND code_set.replaced_at IS NULL GROUP BY code_set.id, code_set.account_id, code_set.issued_at, code_set.version ORDER BY code_set.account_id

mapper.update:
UPDATE iam_recovery_code code
SET used_at = #{usedAt}
FROM iam_recovery_code_set code_set
WHERE code.id = #{codeId}
  AND code.set_id = #{setId}
  AND code.used_at IS NULL
  AND code_set.id = code.set_id
  AND code_set.account_id = #{accountId}
  AND code_set.version = #{setVersion}
  AND code_set.replaced_at IS NULL

mapper.select:
SELECT COUNT(*)
FROM iam_recovery_code code
JOIN iam_recovery_code_set code_set ON code_set.id = code.set_id
WHERE code.id = #{codeId}
  AND code.used_at IS NOT NULL
  AND code_set.account_id = #{accountId}
  AND code_set.version = #{setVersion}
  AND code_set.replaced_at IS NULL
